  mkLRule (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0] 1 0 []))
          (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1;S0] [S0] 1 0 [])) 0 4.
