    exfalso; lia.
  }
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LC_1LC1RA_0LC1RD_1LB0RD | exact ok_iarm1_0_1RB1LC_1LC1RA_0LC1RD_1LB0RD]. }
