  | 1, (StA, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 4]
  | 1, (StB, S0) => [SWin 1;SCycR 1;SWinR 3]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 1;SCycR 1;SWinR 4]
  | 1, (StC, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 3]
  | 1, (StD, S0) => [SWin 1;SCycR 1;SWinR 5]
  | 1, (StD, S1) => []
  | _, _ => []
  end.

