  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1LC0RB_1LD1RA_0LD1RB | exact ok_iarm0_0_1RB1LD_1LC0RB_1LD1RA_0LD1RB]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1LC0RB_1LD1RA_0LD1RB | exact ok_iarm0_1_1RB1LD_1LC0RB_1LD1RA_0LD1RB]. }
    exfalso; lia.
  }
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1LD_1LC0RB_1LD1RA_0LD1RB | exact ok_iarm1_0_1RB1LD_1LC0RB_1LD1RA_0LD1RB]. }
