(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* D[1] L<> R<1^3+y0>  ==>  D[1] L<> R<0^2+y0 1^2>   [10+2*y0 steps] *)
Definition arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1;S1] [S1] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0] 1 0 [S1;S1])) 2 10.
Definition ch_arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 5);RB (SCycR 1);RB (SWinR 2);RB (SRotL 1);RB (SWin 1);RB (SCycL 1 0);RB (SWin 2)].
Lemma ok_arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
  check_arm tm true true rules arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC ch_arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC : RuleSound tm true true arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC.
Proof. eapply arm_sound; [exact rules_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC | exact ok_arm5_1RB1RB_1LC0RB_1LD1LA_0LD1RC]. Qed.

(* D[1] L<> R<0^1+y0 1^2+y1 #^1>  ==>  D[1] L<> R<1^1 0^y0 1^2+y1 #^1>   [2 steps] *)
