  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 2.
Definition ch_arm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 2)].
