          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0] 1 0 [S1;S1])) 2 10.
Definition ch_arm2_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 5);RB (SCycR 1);RB (SWin 2);RB (SRotL 1);RB (SWin 1);RB (SCycL 1 0);RB (SWin 2)].
Lemma ok_arm2_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
