Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm2_1RB1RB_1LC0RB_1LD1LA_0LD1RC : RuleSound tm true false arm2_1RB1RB_1LC0RB_1LD1LA_0LD1RC.
Proof. eapply arm_sound; [exact rules_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC | exact ok_arm2_1RB1RB_1LC0RB_1LD1LA_0LD1RC]. Qed.

(** ** What this board establishes

    5 of 5 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt], at [(Fib, 1)]

    The arms below are the case split of [LadderCheck.fib_split], built from
    the FAMILY rather than mined: one interior arm per CLASS (there are two,
    LADDER_PLAN 4p) and per arm index, and one fill arm per WIDTH index.
    Every certificate arm above is one of these with its run lengths pinned to
    their lower bounds, which is why 5 of them collapse to 5 here.

    The numeration is FIBONACCI: the digit at index [i] carries weight
    1, 1, 2, 3, 5, 8, ... and this width spells [fibsum k + 1] members, not
    [2^k].  It is REDUNDANT -- the first two weights are both 1 -- so which
    string of a width the counter stands on is a MEMBERSHIP predicate and not
    an arithmetic fact, and that predicate is what [fibokb] is.  The two
    classes split on the LOW DIGIT and the top of a width is [1^k].

    The interior class runs at threshold 1 stride 1, the fill
    class at threshold 1 stride 1.  [boardF_neverqh] consumes
    them, the boot, and one chain per state per fill arm. *)
Definition iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 2.
Definition ch_iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 2)].
Lemma ok_iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
  check_arm tm true false rules iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC
            ch_iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0;S0] [S0] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S0] [S0] 1 0 [])) 0 2.
Definition ch_iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 2)].
Lemma ok_iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
  check_arm tm true false rules iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC
            ch_iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S0] [] 0 0 []))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1;S1] [] 0 0 [])) 0 6.
Definition ch_iarm1_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 6)].
