Proof. vm_compute. reflexivity. Qed.

Definition iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [S1] 1 0 [S1;S0]))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0] [S0] 1 0 [S1;S1])) 2 8.
Definition ch_iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 3);RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 1)].
Lemma ok_iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
  check_arm tm true false rules iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC
            ch_iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : LRule :=
  mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [S1] 1 0 [S1;S1]))
          (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S0] [S0] 1 0 [S0;S1;S1])) 2 10.
Definition ch_farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC : list rstep := [RB (SWin 3);RB (SCycR 1);RB (SWin 2);RB (SWinR 4);RB (SCycL 1 0);RB (SWin 1)].
Lemma ok_farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
  check_arm tm true true rules farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC ch_farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RB_1LC0RB_1LD1LA_0LD1RC (i r : nat) : LRule :=
  match i, r with
  | 0, 0 => iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC
  | 0, 1 => iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC
  | 1, 0 => iarm1_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC
  | 1, 1 => iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC
  | _, _ => iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC   (* unreachable: i < 2 and r < N0i + sti *)
  end.

(** The fill arms, indexed by the WIDTH.  Both tails are known empty -- they
    are the only arms that see the end of the counter -- and the left-hand
    side is the top of the width, which here is a BARE run of [1]s.  That is
    both the largest MEMBER and the largest value ([fibsum k]), so unlike
    either other code it needs no fixed word at either end.  [fw1]/[fw2] say
    how the top's concrete copies of the run divide about the block and
    [fm1]/[fm2] the fill target's. *)
Definition farm_1RB1RB_1LC0RB_1LD1LA_0LD1RC (r : nat) : LRule :=
  match r with
  | 1 => farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC
  | _ => farm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC   (* unreachable: 1 <= r < N0f + stf *)
  end.

Definition fw1_1RB1RB_1LC0RB_1LD1LA_0LD1RC (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fw2_1RB1RB_1LC0RB_1LD1LA_0LD1RC (r : nat) : nat := match r with | 1 => 0 | _ => 0 end.
Definition fm1_1RB1RB_1LC0RB_1LD1LA_0LD1RC (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fm2_1RB1RB_1LC0RB_1LD1LA_0LD1RC (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
    and [topsF_cofinal] says the tops keep coming, which is all the liveness
    needs. *)
Definition vis_1RB1RB_1LC0RB_1LD1LA_0LD1RC (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S1) => [SWin 2]
  | 1, (StB, S0) => [SWin 3;SCycR 1;SWinR 3]
  | 1, (StB, S1) => [SWin 3]
  | 1, (StC, S0) => [SWin 3;SCycR 1;SWinR 4]
  | 1, (StC, S1) => [SWin 1]
  | 1, (StD, S0) => [SWin 3;SCycR 1;SWinR 5]
  | 1, (StD, S1) => []
  | _, _ => []
  end.

Lemma iarm_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC : forall i r,
  i < 2 -> r < 1 + 1 ->
  RuleSound tm (negb (fm_left FAM)) (fm_left FAM) (iarm_1RB1RB_1LC0RB_1LD1LA_0LD1RC i r).
Proof.
  intros i r Hi Hr.
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC | exact ok_iarm0_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC | exact ok_iarm0_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC]. }
    exfalso; lia.
  }
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC | exact ok_iarm1_0_1RB1RB_1LC0RB_1LD1LA_0LD1RC]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RB_1LC0RB_1LD1LA_0LD1RC | exact ok_iarm1_1_1RB1RB_1LC0RB_1LD1LA_0LD1RC]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

