Lemma vis_ok_1RB1RB_1LC0RB_1LD1LA_0LD1RC : forall r t, ~ In t pins_1RB1RB_1LC0RB_1LD1LA_0LD1RC -> 1 <= r ->
  r < 1 + 1 ->
  srun_instr tm true true (vis_1RB1RB_1LC0RB_1LD1LA_0LD1RC r t) (lr_lhs (farm_1RB1RB_1LC0RB_1LD1LA_0LD1RC r)) = Some t.
Proof.
  intros r t Hnp H1 Hr.
  destruct r as [|r].
  { exfalso; lia. }
  destruct r as [|r].
  { destruct t as [q s]; destruct q, s; try (exfalso; apply Hnp; simpl; tauto); vm_compute; reflexivity. }
  exfalso; lia.
Qed.

(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    9, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1RB_1LC0RB_1LD1LA_0LD1RC :
  stepn tm_1RB1RB_1LC0RB_1LD1LA_0LD1RC 9 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
