Definition pins_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list Instr := [(StA, S0)].
Local Notation tm := (tm_wrap_trs tm_1RB1RC_1LC1LA_0LC1RD_1LB0RD pins_1RB1RC_1LC1LA_0LC1RD_1LB0RD).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1RC_1LC1LA_0LC1RD_1LB0RD : Fam := mkFam 2 [[S0];[S1]] [] [[S1;S1]] Fib 1 [mkFill 1 [] 0 [] 0] StD S1 false [S1;S1].
Local Notation FAM := fam_1RB1RC_1LC1LA_0LC1RD_1LB0RD.

(** ** The ladder, as DATA

    3 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S0 (mkS [S0] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB1RC_1LC1LA_0LC1RD_1LB0RD.

Definition rules_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list LRule := map fst lad.
Local Notation rules := rules_1RB1RC_1LC1LA_0LC1RD_1LB0RD.

Lemma ladder_ok_1RB1RC_1LC1LA_0LC1RD_1LB0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1RC_1LC1LA_0LC1RD_1LB0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1RC_1LC1LA_0LC1RD_1LB0RD. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* D[1] L<1^2> R<1^3+y0>  ==>  D[1] L<1^2> R<0^2+y0 1^2>   [14+2*y0 steps] *)
Definition arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S1;S1;S1] [S1] 1 0 []))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S0;S0] [S0] 1 0 [S1;S1])) 2 14.
Definition ch_arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list rstep := [RB (SWin 3);RB (SCycR 1);RB (SWinR 2);RB (SRotL 1);RB (SWin 1);RB (SCycL 1 0);RB (SWin 8)].
Lemma ok_arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD :
  check_arm tm true true rules arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD ch_arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD : RuleSound tm true true arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD.
Proof. eapply arm_sound; [exact rules_sound_1RB1RC_1LC1LA_0LC1RD_1LB0RD | exact ok_arm6_1RB1RC_1LC1LA_0LC1RD_1LB0RD]. Qed.

(* D[1] L<1^2> R<0^1+y0 1^2+y1 #^1>  ==>  D[1] L<1^2> R<1^1 0^y0 1^2+y1 #^1>   [4 steps] *)
Definition arm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S0] [] 0 0 []))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 4.
Definition ch_arm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list rstep := [RB (SWin 4)].
Lemma ok_arm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD :
  check_arm tm true false rules arm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD ch_arm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD = true.
