(* D[1] L<1^2> R<1^1 0^1+y0 #^1>  ==>  D[1] L<1^2> R<1^2 0^y0 #^1>   [10 steps] *)
Definition arm15_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
