(* D[1] L<1^2> R<1^1+y0 0^1+y1 1^2+y2 #^1>  ==>  D[1] L<1^2> R<0^y0 1^2 0^y1 1^2+y2 #^1>   [10+2*y0 steps] *)
Definition arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S1;S1] [S1] 1 0 [S0]))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S0] [S0] 1 0 [S1;S1])) 2 12.
Definition ch_arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list rstep := [RB (SWin 2);RB (SCycR 1);RB (SWin 2);RB (SRotL 1);RB (SWin 1);RB (SCycL 1 0);RB (SWin 7)].
Lemma ok_arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD :
  check_arm tm true false rules arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD ch_arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD : RuleSound tm true false arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD.
Proof. eapply arm_sound; [exact rules_sound_1RB1RC_1LC1LA_0LC1RD_1LB0RD | exact ok_arm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD]. Qed.

(** ** What this board establishes

    4 of 4 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt], at [(Fib, 1)]

    The arms below are the case split of [LadderCheck.fib_split], built from
    the FAMILY rather than mined: one interior arm per CLASS (there are two,
    LADDER_PLAN 4p) and per arm index, and one fill arm per WIDTH index.
    Every certificate arm above is one of these with its run lengths pinned to
    their lower bounds, which is why 4 of them collapse to 3 here.

    The numeration is FIBONACCI: the digit at index [i] carries weight
    1, 1, 2, 3, 5, 8, ... and this width spells [fibsum k + 1] members, not
    [2^k].  It is REDUNDANT -- the first two weights are both 1 -- so which
    string of a width the counter stands on is a MEMBERSHIP predicate and not
    an arithmetic fact, and that predicate is what [fibokb] is.  The two
    classes split on the LOW DIGIT and the top of a width is [1^k].

    The interior class runs at threshold 0 stride 1, the fill
    class at threshold 1 stride 1.  [boardF_neverqh] consumes
    them, the boot, and one chain per state per fill arm. *)
Definition iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S0] [S0] 1 0 []))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S1] [S0] 1 0 [])) 0 4.
Definition ch_iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list rstep := [RB (SWin 4)].
Lemma ok_iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD :
  check_arm tm true false rules iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD
            ch_iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [S1] 1 0 [S1;S0]))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [] [S0] 1 0 [S1;S1])) 2 10.
Definition ch_iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list rstep := [RB (SCycR 1);RB (SWin 4);RB (SCycL 1 0);RB (SWin 6)].
Lemma ok_iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD :
  check_arm tm true false rules iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD
            ch_iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD : LRule :=
  mkLRule (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S1] [S1] 1 0 [S1;S1]))
          (mkC StD (mkS [S1;S1] [] 0 0 []) S1 (mkS [S0] [S0] 1 0 [S0;S1;S1])) 2 14.
Definition ch_farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD : list rstep := [RB (SWin 1);RB (SCycR 1);RB (SWin 2);RB (SWinR 4);RB (SCycL 1 0);RB (SWin 7)].
Lemma ok_farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD :
  check_arm tm true true rules farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD ch_farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1RC_1LC1LA_0LC1RD_1LB0RD (i r : nat) : LRule :=
  match i, r with
  | 0, 0 => iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD
  | 1, 0 => iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD
  | _, _ => iarm0_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD   (* unreachable: i < 2 and r < N0i + sti *)
  end.

(** The fill arms, indexed by the WIDTH.  Both tails are known empty -- they
    are the only arms that see the end of the counter -- and the left-hand
    side is the top of the width, which here is a BARE run of [1]s.  That is
    both the largest MEMBER and the largest value ([fibsum k]), so unlike
    either other code it needs no fixed word at either end.  [fw1]/[fw2] say
    how the top's concrete copies of the run divide about the block and
    [fm1]/[fm2] the fill target's. *)
Definition farm_1RB1RC_1LC1LA_0LC1RD_1LB0RD (r : nat) : LRule :=
  match r with
  | 1 => farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD
  | _ => farm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD   (* unreachable: 1 <= r < N0f + stf *)
  end.

Definition fw1_1RB1RC_1LC1LA_0LC1RD_1LB0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fw2_1RB1RC_1LC1LA_0LC1RD_1LB0RD (r : nat) : nat := match r with | 1 => 0 | _ => 0 end.
Definition fm1_1RB1RC_1LC1LA_0LC1RD_1LB0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fm2_1RB1RC_1LC1LA_0LC1RD_1LB0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
    and [topsF_cofinal] says the tops keep coming, which is all the liveness
    needs. *)
Definition vis_1RB1RC_1LC1LA_0LC1RD_1LB0RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 5]
  | 1, (StB, S0) => [SWin 1;SCycR 1;SWinR 4]
  | 1, (StB, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 4]
  | 1, (StC, S0) => [SWin 1;SCycR 1;SWinR 5]
  | 1, (StC, S1) => [SWin 1;SCycR 1;SWin 2;SWinR 4;SCycL 1 0;SWin 2]
  | 1, (StD, S0) => [SWin 1;SCycR 1;SWinR 3]
  | 1, (StD, S1) => []
  | _, _ => []
  end.

Lemma iarm_sound_1RB1RC_1LC1LA_0LC1RD_1LB0RD : forall i r,
  i < 2 -> r < 0 + 1 ->
