  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RC_1LC1LA_0LC1RD_1LB0RD | exact ok_iarm1_0_1RB1RC_1LC1LA_0LC1RD_1LB0RD]. }
    exfalso; lia.
