Definition iarm_1RB1RD_1LC1LA_0LC1RB_1LB0RD (i r : nat) : LRule :=
  match i, r with
  | 0, 0 => iarm0_0_1RB1RD_1LC1LA_0LC1RB_1LB0RD
  | 0, 1 => iarm0_1_1RB1RD_1LC1LA_0LC1RB_1LB0RD
  | 1, 0 => iarm1_0_1RB1RD_1LC1LA_0LC1RB_1LB0RD
  | 1, 1 => iarm1_1_1RB1RD_1LC1LA_0LC1RB_1LB0RD
  | _, _ => iarm0_0_1RB1RD_1LC1LA_0LC1RB_1LB0RD   (* unreachable: i < 2 and r < N0i + sti *)
  end.

(** The fill arms, indexed by the WIDTH.  Both tails are known empty -- they
    are the only arms that see the end of the counter -- and the left-hand
    side is the top of the width, which here is a BARE run of [1]s.  That is
    both the largest MEMBER and the largest value ([fibsum k]), so unlike
    either other code it needs no fixed word at either end.  [fw1]/[fw2] say
    how the top's concrete copies of the run divide about the block and
    [fm1]/[fm2] the fill target's. *)
Definition farm_1RB1RD_1LC1LA_0LC1RB_1LB0RD (r : nat) : LRule :=
  match r with
  | 1 => farm1_1RB1RD_1LC1LA_0LC1RB_1LB0RD
  | _ => farm1_1RB1RD_1LC1LA_0LC1RB_1LB0RD   (* unreachable: 1 <= r < N0f + stf *)
  end.

Definition fw1_1RB1RD_1LC1LA_0LC1RB_1LB0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fw2_1RB1RD_1LC1LA_0LC1RB_1LB0RD (r : nat) : nat := match r with | 1 => 0 | _ => 0 end.
Definition fm1_1RB1RD_1LC1LA_0LC1RB_1LB0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.
Definition fm2_1RB1RD_1LC1LA_0LC1RB_1LB0RD (r : nat) : nat := match r with | 1 => 1 | _ => 0 end.

(** One chain per state per fill arm.  [vis_of_run] turns each into a visit
    and [topsF_cofinal] says the tops keep coming, which is all the liveness
    needs. *)
Definition vis_1RB1RD_1LC1LA_0LC1RB_1LB0RD (r : nat) (t : Instr) : list lstep :=
  match r, t with
  | 1, (StA, S1) => [SWin 2]
  | 1, (StB, S0) => [SWin 3;SCycR 1;SWinR 4]
  | 1, (StB, S1) => [SWin 1]
  | 1, (StC, S0) => [SWin 3;SCycR 1;SWinR 5]
  | 1, (StC, S1) => []
  | 1, (StD, S0) => [SWin 3;SCycR 1;SWinR 3]
  | 1, (StD, S1) => [SWin 3]
  | _, _ => []
  end.

