  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RD_1LC1LA_0LC1RB_1LB0RD | exact ok_iarm0_0_1RB1RD_1LC1LA_0LC1RB_1LB0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RD_1LC1LA_0LC1RB_1LB0RD | exact ok_iarm0_1_1RB1RD_1LC1LA_0LC1RB_1LB0RD]. }
    exfalso; lia.
  }
  destruct i as [|i].
  {
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RD_1LC1LA_0LC1RB_1LB0RD | exact ok_iarm1_0_1RB1RD_1LC1LA_0LC1RB_1LB0RD]. }
    destruct r as [|r].
    { eapply arm_sound; [exact rules_sound_1RB1RD_1LC1LA_0LC1RB_1LB0RD | exact ok_iarm1_1_1RB1RD_1LC1LA_0LC1RB_1LB0RD]. }
    exfalso; lia.
  }
  exfalso; lia.
Qed.

