(** The boot, on the ORIGINAL machine and up to [lift]: the member at index
    16, past the last fire of every pinned instruction. *)
Lemma bootq_1RB1RD_1LC1LA_0LC1RB_1LB0RD :
  stepn tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD 16 InitES = Some (lift (fam_cfg FAM ([0], 0, 0))).
Proof.
  assert (H : match csteps tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD 16 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD 16 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** a pinned instruction fired before the boot: the quasihalt witness *)
Lemma wit_1RB1RD_1LC1LA_0LC1RB_1LB0RD :
  existsb (fun tg => cfires tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD c0 16 tg) pins_1RB1RD_1LC1LA_0LC1RB_1LB0RD = true.
Proof. vm_compute. reflexivity. Qed.

Lemma bnd_1RB1RD_1LC1LA_0LC1RB_1LB0RD : (16 <=? 32779478) = true.
Proof. apply bound_tr_leb; vm_cast_no_check (eq_refl true). Qed.

(** The machine-level theorem, on the QUASIHALTING side
    ([LadderCheckFibTr.boardF_qhtr]). *)
Theorem qhtr_1RB1RD_1LC1LA_0LC1RB_1LB0RD :
  NonHalt tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD /\ QHBoundTr 32779478 tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD /\ QuasiHaltsTr tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
Proof.
  eapply (boardF_qhtr tm_1RB1RD_1LC1LA_0LC1RB_1LB0RD pins_1RB1RD_1LC1LA_0LC1RB_1LB0RD FAM
                      iarm_1RB1RD_1LC1LA_0LC1RB_1LB0RD 1 1
                      farm_1RB1RD_1LC1LA_0LC1RB_1LB0RD 1 1
                      fw1_1RB1RD_1LC1LA_0LC1RB_1LB0RD fw2_1RB1RD_1LC1LA_0LC1RB_1LB0RD fm1_1RB1RD_1LC1LA_0LC1RB_1LB0RD fm2_1RB1RD_1LC1LA_0LC1RB_1LB0RD
                      vis_1RB1RD_1LC1LA_0LC1RB_1LB0RD [0]).
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - vm_compute; repeat constructor.
  - vm_compute; repeat constructor.
  - vm_compute; lia.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - intros k Hk. apply (filled_fib0 FAM 0 k);
      vm_compute; reflexivity.
  - repeat constructor.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - lia.
  - exact iarm_sound_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact iarm_lhs_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact iarm_rhs_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact iarm_cb_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - lia.
  - lia.
  - exact fw_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact fm12_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact farm_sound_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact farm_lhs_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact farm_rhs_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
  - exact farm_cb_1RB1RD_1LC1LA_0LC1RB_1LB0RD.
